-- Material-based insulation pricing. Spray foam is priced per GALLON with a yield in board feet per gallon (barrel = barrel_gal gallons); batts and blown-in per pack with sq ft coverage.
CREATE TABLE IF NOT EXISTS ins_materials(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('foam_open','foam_closed','batt','blown')),pack TEXT NOT NULL DEFAULT 'set',unit_cost REAL NOT NULL DEFAULT 0,pack_gal REAL NOT NULL DEFAULT 0,pack_cover REAL NOT NULL DEFAULT 1,r_per_inch REAL NOT NULL DEFAULT 0,r_fixed REAL NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS ins_materials_company ON ins_materials(company_id);
CREATE TABLE IF NOT EXISTS ins_settings(company_id INTEGER PRIMARY KEY REFERENCES companies(id) ON DELETE CASCADE,crew_size INTEGER NOT NULL DEFAULT 2,gal_per_day REAL NOT NULL DEFAULT 60,crew_day_cost REAL NOT NULL DEFAULT 800,waste_pct REAL NOT NULL DEFAULT 10,markup_pct REAL NOT NULL DEFAULT 35,sqft_per_day REAL NOT NULL DEFAULT 1500,barrel_gal REAL NOT NULL DEFAULT 45);
PRAGMA user_version=18;
